import{_ as t,o,c as a,a3 as n}from"./chunks/framework.vDgOMd_y.js";const u=JSON.parse('{"title":"Interaction and input","description":"","frontmatter":{},"headers":[],"relativePath":"en/guides/interaction.md","filePath":"en/guides/interaction.md"}'),i={name:"en/guides/interaction.md"};function s(r,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /kimiteam/docs/en/guides/interaction.md for this page in Markdown format</div><h1 id="interaction-and-input" tabindex="-1">Interaction and input <a class="header-anchor" href="#interaction-and-input" aria-label="Permalink to &quot;Interaction and input&quot;">​</a></h1><p>Kimi Code CLI runs as an interactive TUI (terminal user interface) built around three components: the input box, the conversation view, and the status bar. This page covers how to enter text, paste media, navigate the approval flow, and switch between modes.</p><h2 id="input-box-basics" tabindex="-1">Input box basics <a class="header-anchor" href="#input-box-basics" aria-label="Permalink to &quot;Input box basics&quot;">​</a></h2><p>The input box accepts free-form text. Press <code>Enter</code> to send, or <code>Shift-Enter</code> / <code>Ctrl-J</code> to insert a newline. When the input box is empty, press <code>↑</code> / <code>↓</code> to browse the input history for the current working directory, including previous shell commands.</p><p><strong>Exiting the CLI</strong>: press <code>Ctrl-D</code> with the input box empty, press <code>Ctrl-C</code> twice while idle, or type <code>/exit</code>. Pressing <code>Ctrl-C</code> or <code>Esc</code> during streaming output interrupts the current turn — it does not exit the program.</p><h2 id="pasting-images-and-video" tabindex="-1">Pasting images and video <a class="header-anchor" href="#pasting-images-and-video" aria-label="Permalink to &quot;Pasting images and video&quot;">​</a></h2><p>Kimi Code CLI supports pasting images and video directly into the input box, so you can discuss screenshots, UI mockups, architecture diagrams, or code demos without uploading or converting files first.</p><p><strong>Video input is a distinctive Kimi Code capability</strong> — you can paste a video clip and have the model analyze its content, UI flow, or code walkthrough.</p><p>How to paste:</p><ul><li><strong>macOS / Linux</strong>: <code>Ctrl-V</code></li><li><strong>Windows</strong>: <code>Alt-V</code></li></ul><p>After pasting, the input box shows a placeholder that you can edit like normal text; on submit, the placeholder is replaced with the actual content. A plain-text clipboard falls back to ordinary paste. Media support depends on the current model&#39;s multimodal capabilities (<code>image_in</code> / <code>video_in</code>); it is enabled by default when you are logged in to a Kimi Code account.</p><h2 id="slash-commands" tabindex="-1">Slash commands <a class="header-anchor" href="#slash-commands" aria-label="Permalink to &quot;Slash commands&quot;">​</a></h2><p>Anything starting with <code>/</code> is treated as a slash command. Typing <code>/</code> opens a completion menu that filters in real time as you keep typing; press <code>Esc</code> to close the menu. If nothing matches, the input is sent to the agent as a regular message.</p><p>Active <a href="./../customization/skills.html">Agent Skills</a> are automatically registered as slash commands: ordinary external Skills are invoked with <code>/skill:&lt;name&gt;</code>, external sub-skills appear as dotted commands such as <code>/parent.child</code>, and built-in Skills appear directly as <code>/&lt;name&gt;</code> in the slash command panel. If an external skill name does not conflict with a system slash command, you can also drop the <code>skill:</code> prefix and type <code>/&lt;name&gt;</code> directly.</p><p>Some commands are only available when the agent is idle — you need to press <code>Esc</code> to interrupt streaming output or context compression before using them. Mode-toggle and query commands like <code>/yolo</code>, <code>/plan</code>, <code>/help</code>, and <code>/btw</code> are always available. For the full list, see <a href="./../reference/slash-commands.html">Slash commands reference</a>.</p><h2 id="file-references" tabindex="-1">File references <a class="header-anchor" href="#file-references" aria-label="Permalink to &quot;File references&quot;">​</a></h2><p>Type <code>@</code> to trigger file-path completion. Selecting a path inserts its relative form into your message; the agent loads the file content directly when it reads the message. File references work in both git and non-git directories, and folder suggestions end with <code>/</code> so you can keep completing paths inside them. If the fast search helper is still downloading, Kimi Code falls back to a basic filesystem scan. Hidden paths are available, but <code>.git</code> is excluded from suggestions.</p><blockquote><p><code>@</code> references and slash commands are two separate mechanisms: <code>@</code> gives the agent file context, while <code>/</code> invokes built-in features or Skills. A <code>/</code> typed after leading whitespace is treated as normal text, not as the slash-command menu.</p></blockquote><h2 id="approval-flow" tabindex="-1">Approval flow <a class="header-anchor" href="#approval-flow" aria-label="Permalink to &quot;Approval flow&quot;">​</a></h2><p>When the agent calls a tool that has side effects — modifying files, running commands — the TUI displays an approval panel for your confirmation. Approvals are not triggered for regular tool calls in YOLO mode, nor for writes to plan files in Plan mode.</p><p>Use the arrow keys to select an option and press <code>Enter</code> to confirm, or press <code>1</code> / <code>2</code> / <code>3</code> to select by number directly. <code>Esc</code>, <code>Ctrl-C</code>, and <code>Ctrl-D</code> are all equivalent to rejecting.</p><p>The panel typically includes an <strong>Approve for this session</strong> option; selecting it auto-approves the same kind of call for the rest of the session. For permanent rules, add allow / deny entries in <a href="./../configuration/config-files.html#permission">Configuration files</a>.</p><h2 id="mode-switching" tabindex="-1">Mode switching <a class="header-anchor" href="#mode-switching" aria-label="Permalink to &quot;Mode switching&quot;">​</a></h2><h3 id="plan-mode" tabindex="-1">Plan mode <a class="header-anchor" href="#plan-mode" aria-label="Permalink to &quot;Plan mode&quot;">​</a></h3><p>In Plan mode the agent first outputs an action plan and waits for your approval before modifying any files — useful for complex or high-risk tasks.</p><ul><li>Toggle: <code>Shift-Tab</code> or <code>/plan</code></li><li>Clear the current plan: <code>/plan clear</code> (only while idle)</li></ul><p>After producing a plan the agent pauses for your review — you can approve it, reject it, or ask for revisions. Exiting Plan mode requires your confirmation even if YOLO mode is also active. Auto mode is the exception: plan exits are approved automatically and marked as &quot;Auto-approved&quot; in the transcript.</p><h3 id="yolo-auto-mode" tabindex="-1">YOLO / Auto mode <a class="header-anchor" href="#yolo-auto-mode" aria-label="Permalink to &quot;YOLO / Auto mode&quot;">​</a></h3><p><strong>YOLO mode</strong> (<code>/yolo</code>) auto-approves regular tool calls, making it suitable for batch tasks you know are safe. It still asks before sensitive actions — accessing sensitive files such as <code>.env</code> or SSH keys, or exiting Plan mode — and the agent can still ask you questions.</p><p><strong>Auto mode</strong> (<code>/auto</code>) is the fully unattended mode: every tool approval is handled automatically, including sensitive files and plan exits, and the agent never asks you questions — it decides everything on its own.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>YOLO mode skips confirmation for file writes and command execution. Only use it in working directories you trust.</p></div><h3 id="shell-mode" tabindex="-1">Shell mode <a class="header-anchor" href="#shell-mode" aria-label="Permalink to &quot;Shell mode&quot;">​</a></h3><p>Shell mode lets you run terminal commands without leaving the conversation. The command output is written into the conversation context, so the agent can see the results in later turns.</p><ul><li>Enter: type <code>!</code> in an empty input box, or paste a command that starts with <code>!</code>.</li><li>Exit: press <code>Backspace</code> or <code>Esc</code> in an empty input box; submitting a command also returns you to normal mode automatically.</li><li>Run in background: while a command is running, press <code>Ctrl+B</code> to move it to a background task.</li><li>Recall previous commands: with the input box empty in shell mode, press <code>↑</code> to browse earlier shell commands; recalling one keeps you in shell mode so it runs as a command again.</li></ul><p>In shell mode the input box shows a <code>!</code> prompt on the left and the border turns violet. For example, you can run <code>!gh auth login</code> to sign in to the GitHub CLI without opening a new terminal, so Kimi can use <code>gh</code> afterward.</p><h2 id="during-streaming-output" tabindex="-1">During streaming output <a class="header-anchor" href="#during-streaming-output" aria-label="Permalink to &quot;During streaming output&quot;">​</a></h2><p>The input box remains usable while the agent is thinking or calling tools, and supports the following extra actions:</p><ul><li><strong><code>Ctrl-S</code></strong>: inject the content in the input box into the running turn immediately, without waiting for it to finish</li><li><strong><code>Esc</code> / <code>Ctrl-C</code></strong>: interrupt the current turn</li><li><strong><code>Ctrl-O</code></strong>: globally toggle the collapsed/expanded state of tool output and compaction summaries</li></ul><h2 id="external-editor" tabindex="-1">External editor <a class="header-anchor" href="#external-editor" aria-label="Permalink to &quot;External editor&quot;">​</a></h2><p>Press <code>Ctrl-G</code> to send the current input content to an external editor. When you save and close, the text is written back into the input box; if you close without saving, the original content is preserved. This is handy when you need to enter large blocks of text or content with complex formatting.</p><p>Editor priority: <code>/editor</code> config → <code>$VISUAL</code> environment variable → <code>$EDITOR</code> environment variable. If none are set, run <code>/editor</code> first to choose a default.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./../reference/keyboard.html">Keyboard shortcuts</a> — full quick-reference table of all shortcuts</li><li><a href="./../reference/slash-commands.html">Slash commands</a> — all built-in commands with descriptions and aliases</li><li><a href="./sessions.html">Sessions and context</a> — how to resume sessions, compress context, and export conversations</li></ul>',44)])])}const m=t(i,[["render",s]]);export{u as __pageData,m as default};
